import type { ScheduleConfiguration } from '@foreman-code/contracts/schedules'

export const sch11Settings = { timezone: 'UTC', enabled: true, policy: 'latest_saved' as const }
export const sch11Once = {
  ...sch11Settings, mode: 'once', localDate: '2030-01-07', time: '10:00',
} satisfies ScheduleConfiguration
export const sch11Minute = {
  ...sch11Settings, mode: 'interval', every: 1, unit: 'minute', anchorAt: '2030-01-07T09:00:00.000Z',
} satisfies ScheduleConfiguration

/** Literal UTC oracles, not values generated by the implementation under test.
 * The same vectors exercise the contract, dispatch planner and real SQL admission.
 * Old dates deliberately test recurrence independently of the machine's clock. */
export interface Sch11ClockCase {
  name: string
  schedule: ScheduleConfiguration
  from: string
  expected: string[]
}
export const sch11ClockCases: Sch11ClockCase[] = [
  {
    name: 'ISO weekdays and a quarter-hour timezone',
    schedule: { ...sch11Settings, mode: 'weekly', weekdays: [5, 1, 3], time: '09:10', timezone: 'Asia/Kathmandu' },
    from: '2030-01-06T23:59:59.999Z',
    expected: ['2030-01-07T03:25:00.000Z', '2030-01-09T03:25:00.000Z', '2030-01-11T03:25:00.000Z'],
  },
  {
    name: 'Sunday is ISO 7 and midnight crosses the UTC date',
    schedule: { ...sch11Settings, mode: 'weekly', weekdays: [7], time: '00:00', timezone: 'Asia/Tokyo' },
    from: '2030-01-05T14:59:59.999Z',
    expected: ['2030-01-05T15:00:00.000Z', '2030-01-12T15:00:00.000Z'],
  },
  {
    name: 'New York weekly spring gap shifts 02:30 by one hour',
    schedule: { ...sch11Settings, mode: 'weekly', weekdays: [7], time: '02:30', timezone: 'America/New_York' },
    from: '2024-03-10T00:00:00.000Z',
    expected: ['2024-03-10T07:30:00.000Z', '2024-03-17T06:30:00.000Z'],
  },
  {
    name: 'New York weekly fold uses only the first 01:30',
    schedule: { ...sch11Settings, mode: 'weekly', weekdays: [7], time: '01:30', timezone: 'America/New_York' },
    from: '2024-11-03T00:00:00.000Z',
    expected: ['2024-11-03T05:30:00.000Z', '2024-11-10T06:30:00.000Z'],
  },
  {
    name: 'Lord Howe thirty-minute spring gap',
    schedule: { ...sch11Settings, mode: 'weekly', weekdays: [7], time: '02:15', timezone: 'Australia/Lord_Howe' },
    from: '2024-10-05T00:00:00.000Z',
    expected: ['2024-10-05T15:45:00.000Z', '2024-10-12T15:15:00.000Z'],
  },
  {
    name: 'Lord Howe thirty-minute fold',
    schedule: { ...sch11Settings, mode: 'weekly', weekdays: [7], time: '01:45', timezone: 'Australia/Lord_Howe' },
    from: '2024-04-06T00:00:00.000Z',
    expected: ['2024-04-06T14:45:00.000Z', '2024-04-13T15:15:00.000Z'],
  },
  {
    name: 'Apia skipped Friday and Saturday deduplicate to one instant',
    schedule: { ...sch11Settings, mode: 'weekly', weekdays: [5, 6], time: '12:00', timezone: 'Pacific/Apia' },
    from: '2011-12-29T00:00:00.000Z',
    expected: ['2011-12-30T22:00:00.000Z', '2012-01-05T22:00:00.000Z', '2012-01-06T22:00:00.000Z'],
  },
  {
    name: 'one-minute elapsed interval keeps sub-minute anchor through a fold',
    schedule: { ...sch11Settings, mode: 'interval', every: 1, unit: 'minute',
      anchorAt: '2024-11-03T05:59:17.250Z', timezone: 'America/New_York' },
    from: '2024-11-03T05:59:17.249Z',
    expected: ['2024-11-03T05:59:17.250Z', '2024-11-03T06:00:17.250Z', '2024-11-03T06:01:17.250Z'],
  },
  {
    name: 'seven-hour elapsed interval does not follow the DST wall clock',
    schedule: { ...sch11Settings, mode: 'interval', every: 7, unit: 'hour',
      anchorAt: '2024-03-09T23:17:00.000Z', timezone: 'America/New_York' },
    from: '2024-03-09T23:16:59.999Z',
    expected: ['2024-03-09T23:17:00.000Z', '2024-03-10T06:17:00.000Z', '2024-03-10T13:17:00.000Z'],
  },
  {
    name: 'once in a gap',
    schedule: { ...sch11Settings, mode: 'once', localDate: '2024-03-10', time: '02:30', timezone: 'America/New_York' },
    from: '2024-03-10T00:00:00.000Z', expected: ['2024-03-10T07:30:00.000Z'],
  },
  {
    name: 'once in a fold',
    schedule: { ...sch11Settings, mode: 'once', localDate: '2024-11-03', time: '01:30', timezone: 'America/New_York' },
    from: '2024-11-03T00:00:00.000Z', expected: ['2024-11-03T05:30:00.000Z'],
  },
  {
    name: 'once on a Gregorian leap day',
    schedule: { ...sch11Settings, mode: 'once', localDate: '2000-02-29', time: '23:59' },
    from: '2000-02-28T23:59:59.999Z', expected: ['2000-02-29T23:59:00.000Z'],
  },
]
